const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = ($input.item.binary && $input.item.binary.data && $input.item.binary.data.mimeType) || 'audio/ogg';
return [{ json: { audio_base64: buffer.toString('base64'), mime_type: mime } }];

const raw = ($input.item.json.candidates && $input.item.json.candidates[0].content.parts[0].text) || '{}';
const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
let data;
try { data = JSON.parse(cleaned); } catch (e) { data = { tabla: 'no_identificada', confianza: 'baja', texto_transcrito: raw, campos: {} }; }
return [{ json: {
  tabla: data.tabla || 'no_identificada',
  confianza: data.confianza || 'baja',
  texto_transcrito: data.texto_transcrito || '',
  campos: data.campos || {},
  from: $('Extraer mensaje').item.json.from,
  phone_number_id: $('Extraer mensaje').item.json.phone_number_id,
} }];

const g = $('Parsear respuesta Gemini').item.json;
const texto = 'No pude identificar a que reporte pertenece tu mensaje. Intenta mencionar si es rendimiento/meta de una actividad, o jornaleros/nomina del dia.\n\nEntendi: ' + (g.texto_transcrito || '(sin texto)');
return [{ json: { mensaje_confirmacion: texto, from: g.from, phone_number_id: g.phone_number_id } }];

const hoy = new Date().toISOString().slice(0,10);
const filas = $input.all().map(i => i.json).filter(r => {
  if (!r.Fecha) return false;
  const f = (r.Fecha instanceof Date) ? r.Fecha.toISOString().slice(0,10) : String(r.Fecha).slice(0,10);
  return f === hoy;
});
let totalJornaleros = 0, totalNomina = 0;
const filasTexto = filas.map(r => {
  totalJornaleros += Number(r['N° Jornaleros']) || 0;
  totalNomina += Number(r['Nómina Total']) || 0;
  return '- ' + (r.Campo||'-') + ' / ' + (r.Lote||'-') + ' - ' + (r.Actividad||'-') + ' (' + (r['N° Jornaleros']||0) + ' jornaleros, resp. ' + (r.Responsable||'-') + ')';
}).join('\n');
const cuerpo_texto = 'Resumen de Actividades Agricolas - ' + hoy + '\n\n' +
  'Actividades registradas: ' + filas.length + '\n' +
  'Total jornaleros: ' + totalJornaleros + '\n' +
  'Nomina total estimada: $' + totalNomina.toFixed(2) + '\n\n' +
  (filasTexto || 'Sin registros para hoy.');
const filasHtml = filas.map(r => '<tr><td>'+(r.Campo||'')+'</td><td>'+(r.Lote||'')+'</td><td>'+(r.Actividad||'')+'</td><td>'+(r.Responsable||'')+'</td><td>'+(r['N° Jornaleros']||'')+'</td><td>'+(r['Nómina Total']||'')+'</td></tr>').join('');
const cuerpo_html = '<h2>Resumen de Actividades Agricolas - ' + hoy + '</h2>' +
  '<p>Actividades registradas: ' + filas.length + '<br>Total jornaleros: ' + totalJornaleros + '<br>Nomina total estimada: $' + totalNomina.toFixed(2) + '</p>' +
  '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Campo</th><th>Lote</th><th>Actividad</th><th>Responsable</th><th>Jornaleros</th><th>Nomina</th></tr>' + filasHtml + '</table>';
return [{ json: { asunto: 'Resumen diario de actividades agricolas - ' + hoy, cuerpo_texto, cuerpo_html, total_actividades: filas.length } }];

const hoy = new Date().toISOString().slice(0,10);
const filas = $input.all().map(i => i.json).filter(r => {
  if (!r.Fecha) return false;
  const f = (r.Fecha instanceof Date) ? r.Fecha.toISOString().slice(0,10) : String(r.Fecha).slice(0,10);
  return f === hoy;
});
if (filas.length === 0) {
  return [{ json: { Fecha: hoy, Campo: '', Lote: '', Actividad: '', Responsable: '', 'N° Jornaleros': '', 'Procedencia / Cuadrilla': '', 'Recursos / Maquinaria': '', 'Costo por Jornal': '', 'Nómina Total': '', Observaciones: 'Sin registros para hoy' } }];
}
return filas.map(r => ({ json: r }));
